  const totalTasks = unitChecklists.reduce((sum, c) => sum + (c.task_list?.length || 0), 0);
  const completedTasks = unitChecklists.reduce((sum, c) => sum + (c.task_list || []).filter(t => t.is_completed).length, 0);
